CREATE TABLE object_directories (id BIGINT AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT, name VARCHAR(120) NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(parent_id) REFERENCES object_directories(id));
CREATE TABLE data_objects (id BIGINT AUTO_INCREMENT PRIMARY KEY, directory_id BIGINT NOT NULL, source_id BIGINT NOT NULL, catalog_name VARCHAR(255) NOT NULL DEFAULT '', schema_name VARCHAR(255) NOT NULL DEFAULT '', table_name VARCHAR(255) NOT NULL, object_type VARCHAR(16) NOT NULL, identity_hash CHAR(64) NOT NULL UNIQUE, display_name VARCHAR(200) NOT NULL, description VARCHAR(1000) NOT NULL DEFAULT '', dataset_id BIGINT, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(directory_id) REFERENCES object_directories(id), FOREIGN KEY(source_id) REFERENCES data_sources(id), FOREIGN KEY(dataset_id) REFERENCES datasets(id));
CREATE TABLE data_object_fields (id BIGINT AUTO_INCREMENT PRIMARY KEY, object_id BIGINT NOT NULL, ordinal_position INTEGER NOT NULL, field_name VARCHAR(255) NOT NULL, native_type VARCHAR(255) NOT NULL, field_length INTEGER, field_scale INTEGER, nullable_state VARCHAR(10) NOT NULL, primary_key_state VARCHAR(10) NOT NULL, remarks VARCHAR(1000), FOREIGN KEY(object_id) REFERENCES data_objects(id), UNIQUE(object_id,ordinal_position));
CREATE TABLE data_object_drafts (object_id BIGINT PRIMARY KEY, definition_json TEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(object_id) REFERENCES data_objects(id));
CREATE TABLE data_object_operations (id VARCHAR(36) PRIMARY KEY, object_id BIGINT, source_id BIGINT NOT NULL, identity_hash CHAR(64) NOT NULL, active_identity CHAR(64) UNIQUE, operation_type VARCHAR(16) NOT NULL, status VARCHAR(32) NOT NULL, target_json TEXT NOT NULL, original_fingerprint CHAR(64), error_message VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(object_id) REFERENCES data_objects(id), FOREIGN KEY(source_id) REFERENCES data_sources(id));
CREATE TABLE data_object_operation_steps (operation_id VARCHAR(36) NOT NULL, step_number INTEGER NOT NULL, statement_text TEXT NOT NULL, risk_text VARCHAR(1000), status VARCHAR(32) NOT NULL, error_message VARCHAR(1000), PRIMARY KEY(operation_id,step_number), FOREIGN KEY(operation_id) REFERENCES data_object_operations(id));
