INSERT INTO role_permissions(role_id,permission) SELECT 1,permission_code FROM permission_catalog WHERE module_code IN ('datasource.object','datasource.object_directory') AND EXISTS (SELECT 1 FROM roles WHERE id=1) AND NOT EXISTS (SELECT 1 FROM role_permissions rp WHERE rp.role_id=1 AND rp.permission=permission_catalog.permission_code);
INSERT INTO menus(id,parent_id,name,menu_type,route_path,component,permission,icon,sort_order,visible,enabled) SELECT COALESCE(MAX(id),0)+1,2,'数据对象','M','/assets/objects','assets/objects','','dataset',50,TRUE,TRUE FROM menus;
